g=[[3]*18 for _ in range(21)]
# Frame coordinates bounds and colors, interior fill 7
for (r0,r1,c0,c1,color) in [(0,3,2,5,4),(6,12,6,12,1),(16,18,10,12,8)]:
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if r in (r0,r1) or c in (c0,c1): g[r][c]=color
            else: g[r][c]=7
print(len(g),set(map(len,g)),set(x for row in g for x in row))
import json
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))

